#pragma once

#include "duckdb/common/string.hpp"
#include "env_source.hpp"
#include "otlp_ingest_limits.hpp"

#include <cstdint>
#include <vector>

namespace duckdb_otlp_server {

//! One mode: its name and the SQL template in src/server/modes/<name>.sql. The table is
//! generated by CMake and ends with a {nullptr, nullptr} entry.
struct ModePreset {
	const char *name;
	const char *sql;
};
extern const ModePreset MODE_PRESETS[];

struct IngestListener {
	duckdb::string uri;
	duckdb::string transport;
	bool otap = false;
};

//! Shared by startup and `doctor`; resolving listeners needs no storage credentials or I/O.
//! When `selection_reason` is non-null it receives a short note naming the setting that
//! selected the transports, for the startup banner.
std::vector<IngestListener> ListenersFromEnv(const EnvSource &env, duckdb::string *selection_reason = nullptr);

//! Whether Quack is enabled, and the address it binds. Shared with `doctor` so the probe
//! targets exactly what startup bound.
bool QuackEnabledFromEnv(const EnvSource &env);
duckdb::string QuackAddrFromEnv(const EnvSource &env);

struct ServerConfig {
	duckdb::string mode;
	duckdb::string database;
	duckdb::string data_dir;
	std::vector<IngestListener> listeners;
	duckdb::string token;
	duckdb::string catalog;
	duckdb::string schema;
	duckdb::string quack_listen_uri;
	duckdb::string quack_http_addr;
	duckdb::string quack_token;
	//! PEM certificate and key Quack serves TLS with. Empty: Quack generates a self-signed pair.
	duckdb::string quack_ssl_cert_file;
	duckdb::string quack_ssl_key_file;
	duckdb::string parquet_export_path;
	//! Where telemetry lands, for the startup banner (the control database holds none of it).
	duckdb::string data_location;
	//! Where object-storage credentials come from, for the startup banner. Set by the preset.
	duckdb::string credentials_source;
	//! Directory DuckDB loads persistent secrets from. Empty keeps $HOME/.duckdb/stored_secrets.
	duckdb::string secret_dir;
	//! The preset LOADs an extension from a local (unsigned) file. DuckDB accepts this setting
	//! only before the database starts.
	bool allow_unsigned_extensions = false;
	bool quack_enabled = false;
	bool dry_run = false;
	//! Set by --no-auth, or implicitly when no token is configured and every listener binds
	//! loopback (`auth_disabled_for_loopback`). A non-loopback bind with no token is an error.
	bool disable_auth = false;
	bool auth_disabled_for_loopback = false;
	//! Which setting selected the transports, for the startup banner.
	duckdb::string transport_selection;
	int startup_timeout_secs = 60;
	uint64_t http_threads = 0;
	uint64_t max_body_bytes = otlp_limits::DEFAULT_MAX_BODY_BYTES;
	uint64_t max_buffered_bytes = otlp_limits::DEFAULT_MAX_BUFFERED_BYTES;
	uint64_t seal_target_bytes = otlp_limits::DEFAULT_SEAL_TARGET_BYTES;
	int64_t seal_max_age_ms = otlp_limits::DEFAULT_SEAL_MAX_AGE_MS;
	uint64_t target_file_size = otlp_limits::DEFAULT_TARGET_FILE_SIZE;
	int64_t maintenance_retention_ms = otlp_limits::DEFAULT_MAINTENANCE_RETENTION_MS;
	//! Comma-separated resource / scope attribute keys to promote into columns (opt-in).
	duckdb::string promote_resource_attributes;
	duckdb::string promote_scope_attributes;

	//! The mode preset, expanded.
	duckdb::string mode_setup_sql;
	//! Contents of the operator's --init-sql script, run after mode setup. Read here rather
	//! than at execution time so `validate` rejects an unreadable script and prints it.
	duckdb::string init_sql;
	duckdb::string init_sql_path;
	//! Variables the preset reads with getenv(). The daemon binds each as the session variable
	//! env_<NAME>, so secret values never appear in the generated SQL text.
	std::vector<duckdb::string> env_variables;

	//! Resolve the whole configuration from `env`: the process environment plus whatever the
	//! command line layered on top.
	static ServerConfig FromEnv(const EnvSource &env);

	//! One otlp_serve/otap_serve call starting every listener against one shared server.
	duckdb::string StartOtlpSql() const;
	duckdb::string StartQuackSql() const;
	//! The running Quack server's URL and TLS fingerprint, for the startup banner.
	duckdb::string QuackEndpointSql() const;
	duckdb::string StopOtlpSql() const;
	duckdb::string StopQuackSql() const;
	duckdb::string BootSql() const;
};

} // namespace duckdb_otlp_server
